(function(){
'use strict';
var a=window.__civilTheoryCompanyModule10Parts=window.__civilTheoryCompanyModule10Parts||[];
a.push.apply(a,[
{"id":"empresario-rural","title":"Empresário rural e registro facultativo","basis":"CC, arts. 970 e 971; STJ, Tema 1.145","text":"O empresário cuja atividade rural constitua sua principal profissão pode requerer inscrição no Registro Público de Empresas Mercantis. Depois de inscrito, equipara-se, para todos os efeitos, ao empresário sujeito a registro.","sections":[{"title":"Natureza do registro","bullets":["Para o empresário rural, a inscrição é facultativa, diferentemente da regra do art. 967 para o empresário comum.","A inscrição produz sujeição ao regime empresarial a partir do registro, sem apagar a atividade rural anteriormente exercida.","O art. 971 também passou a prever hipótese específica para associação que desenvolva atividade futebolística habitual e profissional."]},{"title":"Recuperação judicial","bullets":["Tema 1.145/STJ: produtor rural que exerce atividade empresarial há mais de dois anos pode requerer recuperação judicial se estiver inscrito na Junta Comercial quando formalizar o pedido.","O tempo de registro pode ser inferior a dois anos; o biênio pode ser demonstrado pelo exercício material da atividade empresarial rural.","Registro deve existir no momento do pedido recuperacional."]}],"table":{"headers":["Situação","Registro"],"rows":[["Empresário comum","Obrigatório"],["Empresário rural","Facultativo"],["Recuperação judicial do rural","Deve estar inscrito quando requerer"]]},"example":"Produtor rural exerce atividade organizada há cinco anos e registra-se há seis meses. O tempo anterior pode contar para o biênio da recuperação judicial, desde que esteja inscrito no momento do pedido.","trap":"Não exija dois anos de registro na Junta para o produtor rural: o Tema 1.145 distingue tempo de atividade empresarial e tempo de registro.","memorize":["Rural: registro facultativo.","Após registro: equiparação ao empresário comum.","Tema 1.145: inscrição no momento do pedido + atividade empresarial por mais de 2 anos."]},
{"id":"capacidade-impedimentos","title":"Capacidade, impedimentos e continuação da empresa pelo incapaz","basis":"CC, arts. 972 a 976","text":"Podem exercer atividade de empresário os plenamente capazes e não impedidos por lei. O impedido que exerce empresa responde pelas obrigações assumidas. O incapaz não inicia livremente empresa, mas pode continuar atividade preexistente nas hipóteses legais, com controle judicial.","sections":[{"title":"Capacidade e impedimento","bullets":["Pleno gozo da capacidade civil + ausência de impedimento legal são pressupostos do art. 972.","Impedido que exerce empresa não usa a própria irregularidade para escapar das obrigações.","Impedimento é restrição legal ao exercício, não incapacidade civil em sentido geral."]},{"title":"Continuação pelo incapaz","bullets":["Pode continuar empresa antes exercida por ele enquanto capaz, por seus pais ou pelo autor da herança.","Exige representação ou assistência e autorização judicial após exame de riscos e conveniência.","Autorização pode ser revogada, preservados direitos de terceiros.","Bens que o incapaz já possuía e que sejam estranhos ao acervo empresarial podem ser protegidos nos termos do alvará."]},{"title":"Sócio incapaz","bullets":["Não pode exercer administração.","Capital social deve estar totalmente integralizado.","Relativamente incapaz é assistido e absolutamente incapaz é representado."]}],"table":{"headers":["Situação","Regra"],"rows":[["Capaz não impedido","Pode exercer empresa"],["Impedido","Responde pelas obrigações se exercer"],["Incapaz","Pode continuar empresa com autorização judicial"],["Sócio incapaz","Sem administração + capital integralizado"]]},"example":"Menor herda empresa individual. A atividade pode ser continuada por representação, se houver autorização judicial e avaliação da conveniência.","trap":"O Código permite continuação, não livre início de nova empresa individual pelo incapaz.","memorize":["Art. 973: impedido responde.","Art. 974: incapaz pode continuar.","Sócio incapaz não administra e exige capital integralizado."]},
{"id":"empresario-casado","title":"Empresário casado, sociedade entre cônjuges e outorga conjugal","basis":"CC, arts. 977 a 980","text":"O Código Civil cria regras especiais para o empresário casado, distinguindo participação societária entre cônjuges, atos sobre imóveis empresariais e publicidade das relações patrimoniais relevantes.","sections":[{"title":"Sociedade entre cônjuges","bullets":["Cônjuges podem contratar sociedade entre si ou com terceiros, desde que não sejam casados em comunhão universal nem separação obrigatória.","A restrição do art. 977 é específica e não alcança todos os regimes de bens."]},{"title":"Imóveis empresariais","bullets":["Art. 978: empresário casado pode alienar ou gravar imóveis que integrem o patrimônio da empresa sem outorga conjugal, qualquer que seja o regime de bens.","A regra é exceção importante ao regime geral de autorização conjugal.","Devem ser arquivados e averbados os pactos e declarações antenupciais e outros atos relevantes previstos nos arts. 979 e 980."]}],"table":{"headers":["Tema","Regra"],"rows":[["Sociedade entre cônjuges","Vedada em comunhão universal e separação obrigatória"],["Imóvel do patrimônio empresarial","Dispensa outorga conjugal"],["Regime de bens","Informação relevante ao registro"]]},"example":"Empresário casado em comunhão parcial vende imóvel que integra o patrimônio de sua empresa individual. O art. 978 dispensa outorga conjugal.","trap":"A dispensa do art. 978 não significa que todo imóvel particular do empresário possa ser alienado sem autorização; a regra fala dos imóveis que integrem o patrimônio da empresa.","memorize":["Art. 977: restrição entre cônjuges.","Art. 978: imóvel empresarial sem outorga.","Qualquer regime de bens para a dispensa do art. 978."]},
{"id":"eireli-slu","title":"EIRELI revogada e sociedade limitada unipessoal","basis":"CC, art. 1.052, §§ 1º e 2º; Lei 14.195/2021","text":"A EIRELI deixou de integrar o sistema vigente. Hoje, a sociedade limitada pode ser constituída por uma ou mais pessoas, permitindo limitada unipessoal sem a antiga estrutura da EIRELI.","sections":[{"title":"Sociedade limitada unipessoal","bullets":["Pode haver apenas um sócio desde a constituição ou por concentração posterior das quotas.","Aplicam-se ao documento constitutivo do sócio único, no que couber, as regras do contrato social.","Não há exigência legal geral de capital mínimo equivalente a múltiplos do salário-mínimo como existia na antiga EIRELI."]},{"title":"EIRELI","bullets":["O art. 980-A foi revogado.","EIRELIs existentes foram transformadas conforme a legislação de transição em sociedades limitadas unipessoais.","Questões que tratam EIRELI como opção atual de constituição empresarial estão desatualizadas."]}],"table":{"headers":["Figura","Situação atual"],"rows":[["EIRELI","Revogada"],["Limitada unipessoal","Vigente"],["Número de sócios na limitada","1 ou mais"]]},"example":"Pessoa deseja estruturar atividade com responsabilidade limitada sem sócio de fachada. Pode constituir sociedade limitada unipessoal.","trap":"Não confunda empresário individual com sociedade limitada unipessoal: o primeiro é pessoa natural exercendo empresa; a segunda é pessoa jurídica societária.","memorize":["EIRELI: revogada.","LTDA pode ter 1 ou mais pessoas.","SLU ≠ empresário individual."]},
{"id":"sociedades","title":"Sociedade: conceito; sociedade simples e sociedade empresária","basis":"CC, arts. 981 a 985","text":"Sociedade nasce do vínculo pelo qual pessoas se obrigam a contribuir com bens ou serviços para atividade econômica e partilha de resultados. A classificação entre simples e empresária depende, em regra, da natureza da atividade, ressalvadas exceções legais.","sections":[{"title":"Contrato de sociedade","bullets":["Contribuição pode envolver bens ou serviços, conforme o tipo societário.","A atividade pode restringir-se a um ou mais negócios determinados.","A sociedade adquire personalidade com a inscrição de seus atos constitutivos no registro próprio, ressalvadas figuras não personificadas."]},{"title":"Simples x empresária","bullets":["Sociedade empresária: exerce atividade própria de empresário sujeito a registro.","Sociedade simples: as demais, ressalvadas exceções expressas.","Sociedade por ações é empresária independentemente do objeto.","Cooperativa é simples independentemente do objeto."]}],"table":{"headers":["Sociedade","Regra"],"rows":[["Empresária","Atividade própria de empresário"],["Simples","Demais atividades"],["S/A","Sempre empresária"],["Cooperativa","Sempre simples"]]},"example":"Cooperativa que atua em atividade economicamente complexa continua classificada como simples por determinação expressa do art. 982, parágrafo único.","trap":"Sociedade limitada não é sempre empresária; sua classificação depende da atividade, ao contrário da sociedade por ações.","memorize":["Art. 981: contribuição + atividade econômica + resultados.","S/A sempre empresária.","Cooperativa sempre simples."]},
{"id":"sociedade-comum","title":"Sociedade em comum","basis":"CC, arts. 986 a 990","text":"Enquanto não inscritos os atos constitutivos, a sociedade sujeita-se ao regime da sociedade em comum, salvo regras próprias de sociedade por ações em organização. É sociedade não personificada, com disciplina patrimonial e responsabilidade específicas.","sections":[{"title":"Prova e patrimônio especial","bullets":["Sócios, nas relações entre si ou com terceiros, em regra só podem provar a existência da sociedade por escrito; terceiros podem prová-la por qualquer meio.","Bens e dívidas sociais formam patrimônio especial de titularidade comum dos sócios.","Bens sociais respondem pelos atos de gestão praticados por qualquer sócio, salvo pacto expresso limitativo conhecido pelo terceiro."]},{"title":"Responsabilidade dos sócios","bullets":["Todos respondem solidária e ilimitadamente pelas obrigações sociais.","É excluído do benefício de ordem aquele que contratou pela sociedade.","Ausência de personalidade não significa inexistência de disciplina jurídica."]}],"table":{"headers":["Tema","Sociedade em comum"],"rows":[["Personalidade","Não"],["Patrimônio","Especial"],["Responsabilidade","Solidária e ilimitada"],["Prova por terceiro","Qualquer meio"]]},"example":"Sociedade começa a atuar antes do registro. Perante credores, aplica-se o regime da sociedade em comum e os sócios podem responder ilimitadamente.","trap":"Sociedade sem registro não é juridicamente invisível; o Código disciplina patrimônio e responsabilidade.","memorize":["Não personificada.","Terceiro prova por qualquer meio.","Responsabilidade solidária e ilimitada."]}
]);
})();
